SELECT 
FROM tianquan_oauth.oauth_audit
WHERE tenant_id = #{tenantId} AND audit_kind = 'OAUTH' AND deleted_at IS NULL
  AND occurred_at >= #{fromInclusive} AND occurred_at < #{toExclusive}

  AND (occurred_at < #{afterOccurredAt}
       OR (occurred_at = #{afterOccurredAt} AND id < #{afterId}))

ORDER BY occurred_at DESC, id DESC
LIMIT #{limit}

SELECT 
FROM tianquan_oauth.oauth_audit
WHERE tenant_id = #{tenantId} AND occurred_at <= #{cutoff}
  AND id > #{afterId} AND deleted_at IS NULL
ORDER BY id ASC
LIMIT #{limit}

SELECT 
FROM tianquan_oauth.oauth_audit
WHERE tenant_id = #{tenantId} AND audit_kind = 'IDENTITY' AND deleted_at IS NULL
AND actor_sub = #{actorSub}
AND event_type = #{eventType}
AND result = #{result}
AND trace_id = #{traceId}
AND occurred_at >= #{from}
AND occurred_at < #{to}
ORDER BY occurred_at DESC, public_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM tianquan_oauth.oauth_audit
WHERE tenant_id = #{tenantId} AND audit_kind = 'IDENTITY' AND deleted_at IS NULL
AND actor_sub = #{actorSub}
AND event_type = #{eventType}
AND result = #{result}
AND trace_id = #{traceId}
AND occurred_at >= #{from}
AND occurred_at < #{to}

SELECT FROM tianquan_oauth.oauth_audit WHERE tenant_id = #{tenantId} AND deleted_at IS NULL AND id IN
#{id}
ORDER BY id ASC

